// Keep the title and controls visible while only the contents scroll.
let menuSurface='',menuDirection=null,menuRepeat=0;
// Allow human D-pad chords to arrive a few frames apart, only on tree nodes.
let treePadChord=null;
function treePadDirection(dx,dy,dt){
 const zero={x:0,y:0},key=dx+','+dy;
 if(!dx&&!dy){const pending=treePadChord;treePadChord=null;return pending&&!pending.sent?{x:pending.x,y:pending.y}:zero;}
 if(dx&&dy){treePadChord={x:dx,y:dy,key,age:0,sent:true,diagonal:true};return {x:dx,y:dy};}
 // Releasing one half of a diagonal must not step sideways before full release.
 if(treePadChord?.diagonal)return zero;
 if(!treePadChord||treePadChord.key!==key)treePadChord={x:dx,y:dy,key,age:0,sent:false};
 else treePadChord.age+=Math.max(0,dt);
 if(treePadChord.age<.08)return zero;
 treePadChord.sent=true;return {x:dx,y:dy};
}
function menuHintText(){if(menuSurface==='inventory')return 'L/R：タブ　−：使い方　右スティック：スクロール';if(menuSurface==='gems')return '十字キー：選択　A：決定　B：戻る　L/R：タブ　右スティック：スクロール';let action=tutorialButton('accept'),back=tutorialButton('back');return (['inventory','gems','skills','stash'].includes(menuSurface)?'L / R：装備・ジェム・成長・倉庫を切替 · ':'')+'十字キー：上下左右に選択 · '+action+'：決定 · '+back+'：戻る · 右スティック：説明をスクロール'+(menuSurface==='skills'?' · 左スティック：ツリー移動':'')}
function frameMenu(kind){let card=$('card');if(!card||card.querySelector('.panel-heading'))return;menuSurface=kind;treePadChord=null;card.dataset.surface=kind;padCursor.active=false;menuDirection=null;menuRepeat=0;let focused=document.activeElement;let heading=document.createElement('div'),body=document.createElement('div');heading.className='panel-heading';body.className='panel-body';for(let child of Array.from(card.children)){if((child.matches('.close,.guild-region,.tabs,h2,#inventoryPadHint')||(child.tagName==='LABEL'&&!child.querySelector('input,select,button,textarea'))))heading.append(child);else body.append(child)}let hint=document.createElement('p');hint.className='panel-controls';hint.textContent=menuHintText();heading.append(hint);card.replaceChildren(heading,body);card.classList.add('framed-panel');card.scrollTop=0;if(kind==='inventory'){inventoryDetailLayout();return}if(focused&&card.contains(focused)){focused.focus({preventScroll:true});menuReveal(focused)}}
function menuReveal(el){$('card').scrollTop=0;let inventoryPane=el.closest?.('.inventory-list,.inventory-detail,.guild-quest-list,.guild-quest-detail,.job-hall,.job-detail');if(inventoryPane){menuRevealWithin(inventoryPane,el);el=inventoryPane;}let tree=$('treeViewport');if(tree?.contains(el)){menuRevealWithin(tree,el,true);el=tree;}let body=$('card').querySelector('.panel-body');if(body?.contains(el)){let r=el.getBoundingClientRect(),b=body.getBoundingClientRect();if(r.height>b.height)body.scrollTop+=r.top-b.top-8;else if(r.top<b.top+8)body.scrollTop+=r.top-b.top-8;else if(r.bottom>b.bottom-8)body.scrollTop+=r.bottom-b.bottom+8;}if(document.activeElement&&tree?.contains(document.activeElement))menuRevealWithin(tree,document.activeElement,true);// Never scroll the document or the fixed heading.
}
function menuControlAvailable(el){if(!el||el.disabled||el.matches?.(':disabled')||el.closest?.('[hidden],[inert]'))return false;let r=el.getBoundingClientRect();if(!r.width||!r.height)return false;let style=getComputedStyle(el);return style.visibility!=='hidden'&&style.visibility!=='collapse'&&style.display!=='none'}
function menuAdjustRange(el,direction){if(!el||el.type!=='range'||!$('card').contains(el)||!menuControlAvailable(el))return false;if(typeof revealMenuCursorFirst==='function'&&revealMenuCursorFirst())return false;let before=el.value;el.stepUp(Math.sign(direction));if(el.value===before)return false;el.dispatchEvent(new Event('input',{bubbles:true}));playSound('ui');return true}
function menuFocusables(){return Array.from($('card').querySelectorAll('button:not(:disabled),select:not(:disabled),input:not(:disabled),textarea:not(:disabled),summary,[role="button"]')).filter(menuControlAvailable)}
function menuTabKeyDown(e){if(e.key!=='Tab'||!paused||!$('card').classList.contains('framed-panel'))return;let items=menuFocusables();e.preventDefault();e.stopImmediatePropagation();if(!items.length)return;let index=items.indexOf(document.activeElement),next=index<0?(e.shiftKey?items.length-1:0):(index+(e.shiftKey?-1:1)+items.length)%items.length;menuFocusElement(items[next]);padCursor.active=false;}
addEventListener('keydown',menuTabKeyDown,true);
function menuMove(dx,dy){let items=menuFocusables();if(!items.length)return;let active=document.activeElement,current=items.indexOf(active),rects=items.map(el=>el.getBoundingClientRect());if(current<0&&$('card').contains(active)&&menuControlAvailable(active)){current=rects.length;rects.push(active.getBoundingClientRect());}let index=current<0?0:inventoryNextIndex(rects,current,dx,dy);let target=items[index];if(!target)return;menuFocusElement(target);padCursor.active=false;playSound('ui')}
function menuActivate(){let el=document.activeElement;if(!el||!$('card').contains(el)||el.disabled){menuMove(0,1);return}if(el.dataset?.node!==undefined){inspectNode(+el.dataset.node);let buy=$('nodeDetail')?.querySelector('button:not(:disabled)');if(buy){buy.focus({preventScroll:true});menuReveal(buy)}return}if(el.tagName==='SELECT'){for(let i=0;i<el.options.length;i++){el.selectedIndex=(el.selectedIndex+1)%el.options.length;if(!el.options[el.selectedIndex].disabled)break}el.dispatchEvent(new Event('change',{bubbles:true}))}else if(el.type==='range'){return menuAdjustRange(el,1)}else if(typeof el.click==='function')el.click();else el.dispatchEvent(new MouseEvent('click',{bubbles:true}));playSound('ui')}
const framePanelBase=panel;panel=kind=>{framePanelBase(kind);if(started&&!dead)frameMenu(tutorialGuideOpen?'tutorial':kind)};
const frameSettingsBase=showControllerSettings;showControllerSettings=()=>{frameSettingsBase();frameMenu('settings')};
const frameTutorialBase=tutorialShow;tutorialShow=page=>{frameTutorialBase(page);frameMenu('tutorial')};
const frameWelcomeBase=welcome;welcome=()=>{$('card').classList.remove('framed-panel');menuSurface='';frameWelcomeBase()};
const frameCloseBase=closePanel;closePanel=()=>{treePadChord=null;menuSurface='';$('card').classList.remove('framed-panel');frameCloseBase()};
// Inventory retains its two-level item/action navigation. Other menus use spatial focus.
const framePadMenuBase=padMenu;padMenu=(g,left,right,dt)=>{let tabs=['inventory','gems','skills','stash'];if(tabs.includes(menuSurface)&&!tutorialGuideOpen&&!padSettingsOpen){let step=padButtonEdge(g,4)?-1:padButtonEdge(g,5)?1:0;if(step){panel(tabs[(tabs.indexOf(menuSurface)+step+tabs.length)%tabs.length]);return}}if(inventoryNav.open){if(padEdge(g,'secondary')){inventoryJump(false);return}if(padEdge(g,'attack')){inventoryJump(true);return}menuScroll(right,dt);framePadMenuBase(g,left,right,dt);return}if(padEdge(g,'back')&&(menuGemBack()||menuTreeBack()))return;if(padEdge(g,'back')||padEdge(g,'pause')){framePadMenuBase(g,{x:0,y:0,magnitude:0},{x:0,y:0,magnitude:0},dt);return}let down=i=>!!g.buttons[i]&&(g.buttons[i].pressed||g.buttons[i].value>.5),dx=Number(down(15))-Number(down(14)),dy=Number(down(13))-Number(down(12));let vp=$('treeViewport');if(menuSurface==='skills'&&vp&&left.magnitude){vp.scrollLeft+=left.x*600*dt;vp.scrollTop+=left.y*600*dt}else if(!dx&&!dy&&left.magnitude>.55){if(Math.abs(left.x)>Math.abs(left.y))dx=Math.sign(left.x);else dy=Math.sign(left.y)}if(menuSurface==='skills'&&vp?.contains(document.activeElement)&&document.activeElement?.dataset.node!==undefined){const direction=treePadDirection(dx,dy,dt);dx=direction.x;dy=direction.y;}else{treePadChord=null;if(dx)dy=0;}let direction=dx||dy?dx+','+dy:null;menuRepeat-=dt;if(direction&&(direction!==menuDirection||menuRepeat<=0)){let el=document.activeElement;if(el?.type==='range'&&dx){menuAdjustRange(el,dx)}else menuMove(dx,dy);menuRepeat=direction===menuDirection?.14:.36}menuDirection=direction;menuScroll(right,dt);if(padEdge(g,'accept'))menuActivate()};
// Reapply scrolling inside the bounded body after inventory focus changes.
const frameInventoryFocus=inventoryFocus;inventoryFocus=()=>{frameInventoryFocus();let el=document.activeElement;if(el&&$('card').contains(el))menuReveal(el)};
addEventListener('keydown',e=>{if(!paused||inventoryNav.open||!$('card').classList.contains('framed-panel'))return;if(/^(INPUT|SELECT|TEXTAREA)$/.test(e.target?.tagName||''))return;let d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(d){e.preventDefault();e.stopImmediatePropagation();menuMove(...d)}},true);

addEventListener('focusin',e=>{if($('card').classList.contains('framed-panel')&&$('card').contains(e.target))menuReveal(e.target)});

function menuScroll(stick,dt){padCursor.active=false;let questSelected=$('guildQuestDetail')&&document.activeElement?.closest?.('.guild-board'),body=$('card').querySelector(inventoryNav.open?'.inventory-detail':questSelected?'.guild-quest-detail':'.panel-body');if(body&&stick.magnitude>.15){body.scrollTop+=stick.y*500*dt;body.scrollLeft+=stick.x*500*dt}}
// Resizing changes pane heights without changing focus. Reveal it after layout settles.
function menuResizeReveal(){if(!paused||!$('card').classList.contains('framed-panel'))return;let active=document.activeElement;if(active&&$('card').contains(active))menuReveal(active)}
addEventListener('resize',()=>requestAnimationFrame(menuResizeReveal));

// Reveal nested tree coordinates without moving the panel heading or document.
function menuRevealWithin(container,el,horizontal=false){let r=el.getBoundingClientRect(),b=container.getBoundingClientRect(),pad=16;let bottom=b.bottom;if(container.id==='treeViewport'){let detail=$('nodeDetail')?.getBoundingClientRect();if(detail&&detail.top>b.top&&detail.top<bottom)bottom=detail.top}if(r.top<b.top+pad)container.scrollTop+=r.top-b.top-pad;else if(r.bottom>bottom-pad)container.scrollTop+=r.bottom-bottom+pad;if(horizontal){if(r.left<b.left+pad)container.scrollLeft+=r.left-b.left-pad;else if(r.right>b.right-pad)container.scrollLeft+=r.right-b.right+pad}}
function menuTreeFocus(){let node=$('card').querySelector('[data-node="'+treeFocus+'"]');if(node){node.focus({preventScroll:true});menuReveal(node)}return node}
function menuTreeBack(){let detail=$('nodeDetail');if(menuSurface!=='skills'||!detail?.contains(document.activeElement))return false;menuTreeFocus();playSound('ui');return true}
const menuBuyNodeBase=buyNode;buyNode=id=>{menuBuyNodeBase(id);if(menuSurface==='skills'){treeFocus=id;menuTreeFocus()}};
addEventListener('keydown',e=>{if(e.key==='Escape'&&paused&&menuTreeBack()){e.preventDefault();e.stopImmediatePropagation()}},true);

// A select rebuilds the gem panel: restore its focus so further A presses work.
function menuFocusElement(el){if(!el)return;el.focus({preventScroll:true});menuReveal(el)}
const menuBindSkillBase=bindSkill;bindSkill=(index,type)=>{let result=menuBindSkillBase(index,type);if(menuSurface==='gems'){let select=$('card').querySelectorAll('.bindings select')[index];if(select)select.value=p.bindings[index];menuFocusElement(select)}return result};
const menuSocketGemBase=socketGem;socketGem=(slot,index)=>{menuSocketGemBase(slot,index);if(menuSurface==='gems')menuFocusElement($('card').querySelector('[data-socket-slot="'+slot+'"][data-socket-index="'+index+'"]'))};
const menuChooseGemBase=chooseGem;chooseGem=index=>{menuChooseGemBase(index);if(menuSurface!=='gems'||selectedGem===null)return;let gem=p.gems[selectedGem],targets=[];for(let slot of GEAR_SLOTS)for(let [i,socket] of (p[slot]?.sockets||[]).entries())if(socket.color==='W'||socket.color===GEM[gem.type].color)targets.push({slot,index:i,filled:!!socket.gem});targets.sort((a,b)=>Number(a.filled)-Number(b.filled));let hint=$('card').querySelector('.panel-controls');if(hint)hint.textContent=GEM[gem.type].name+'を選択中 · 同色の穴でA：装着 · B：選択を取消 · '+menuHintText();if(padActive&&targets.length){let target=targets[0];menuFocusElement($('card').querySelector('[data-socket-slot="'+target.slot+'"][data-socket-index="'+target.index+'"]'))}if(!targets.length)say('対応する色のソケットがありません。Bで選択を取り消せます')};
function menuGemBack(){if(menuSurface!=='gems'||selectedGem===null)return false;let index=selectedGem;selectedGem=null;panel('gems');menuFocusElement($('card').querySelectorAll('.gemcard')[index]);playSound('ui');return true}
addEventListener('keydown',e=>{if(e.key==='Escape'&&paused&&menuGemBack()){e.preventDefault();e.stopImmediatePropagation()}},true);



